        body { font-family: Arial, sans-serif; margin: 30px; }
        #joke { margin-top: 20px; font-size: 1.2rem; }
        button { padding: 10px 20px; font-size: 1rem; }
    </style>
</head>
<body>
    <h1>Chào mừng đến với trang cười!</h1>
