    <div id="joke"></div>

    <script>
        const jokes = [
            "Tại sao con cá không được học tiếng Anh? Vì nó luôn “swim” mà không “speak”.",
            "Bác sĩ nói: 'Bạn cần nhiều nước'. Tôi hỏi: 'Nước gì?' Bác sĩ trả lời: 'Nước uống, không phải nước cá'.",
            "Tại sao cây cối không bao giờ nói chuyện với nhau? Vì chúng luôn “leaf” (lành) và không muốn “leaf” (để lại) lời lẽ.",
